-- Article demandé par Tom le 27/10/2026 : témoignage d'Éric Fallou (faits présentés au conditionnel, gardien non nommé). Règles FIFA vérifiées (Code disciplinaire, art. 15).
INSERT INTO "articles" ("title", "slug", "dek", "body_html", "format", "status", "category_id", "author_id", "created_by", "published_at", "updated_content_at", "reading_minutes", "featured")
SELECT '« Sale nègre de merde » : le racisme frappe encore, en Andorre cette fois', 'racisme-en-andorre-eric-fallou-denonce-des-insultes-racistes', 'Dimanche 25 octobre, lors du match Ordino-Carroi (3-2) en championnat d''Andorre, ⭐ Éric Fallou, joueur de Carroi, affirme avoir été victime d''insultes racistes. Passe D lui apporte tout son soutien.', '<p>Il jouait la 93e minute. Le match touchait à sa fin, et pourtant tout s''est arrêté pour lui. Selon ⭐ Éric Fallou, le gardien de but d''Ordino l''aurait traité de « sale nègre de merde ». Des mots d''une violence inouïe, prononcés sur un terrain de football, en 2026.</p><p>La suite a été un chaos. Les joueurs des deux équipes sont rentrés sur le terrain, la tension est montée d''un cran, et le match a basculé dans la confusion. Fait grave : l''arbitre n''a pas arrêté la rencontre.</p><h2>Notre soutien total à Éric Fallou</h2><p>À Passe D, on le dit sans détour : ⭐ Éric Fallou a tout notre soutien. Aucun joueur ne devrait entendre ça. Ni à la 93e minute, ni à aucune autre. Le racisme n''a pas sa place dans le football, ni ailleurs.</p><p>Le président de Carroi a porté plainte. Si les faits sont prouvés, nous espérons que le gardien sera sanctionné avec la plus grande sévérité. Pas de demi-mesure, pas d''excuse, pas de « c''est le feu du match ».</p><h2>Ce que disent les règles de la FIFA</h2><p>La FIFA a pourtant fixé un cadre clair :</p><ul><li>Le Code disciplinaire de la FIFA (article 15) prévoit une suspension d''au moins 10 matchs pour un joueur reconnu coupable de discrimination ou de propos racistes.</li><li>La procédure en trois étapes donne à l''arbitre le pouvoir d''interrompre le match, puis de le suspendre en renvoyant les équipes aux vestiaires, et enfin de l''arrêter définitivement si les insultes continuent.</li><li>Les fédérations nationales, dont la Fédération andorrane de football, sont tenues d''appliquer ces règles dans leurs propres compétitions.</li></ul><p>Dimanche, la première étape n''a même pas été franchie. C''est aussi ça qu''il faudra expliquer.</p><h2>Nous demandons des réponses</h2><p>Nous appelons la Fédération andorrane de football à ouvrir une enquête rapide et transparente sur la plainte déposée par le président de Carroi. Nous appelons la FIFA, garante de la lutte contre le racisme dans le football mondial, à suivre ce dossier de près et à veiller à ce que ses règles soient respectées. Et nous voulons savoir pourquoi l''arbitre n''a pas interrompu la rencontre.</p><p>Le football se dit uni contre le racisme. Il est temps de le prouver, aussi dans les petits championnats, loin des caméras.</p><p><strong>Non au racisme.</strong> ✊🏿</p><p>— Passe D</p>', 'article', 'published',
  (SELECT "id" FROM "categories" WHERE "slug" = 'actualites'),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
